using namespace std;

using ll = long long;

const ll lots = 1000000009LL;

int n, h;
vector<ll> plough;

struct State {
    int n, a, b, c, d;

    bool operator==(const State& other) const {
        return n == other.n && a == other.a && b == other.b &&
               c == other.c && d == other.d;
    }
};

struct StateHash {
    size_t operator()(const State& s) const {
        size_t seed = 0;
        const int values[] = {s.n, s.a, s.b, s.c, s.d};
        for (int value : values) {
            seed ^= hash<int>{}(value) + 0x9e3779b9U +
                    (seed << 6) + (seed >> 2);
        }
        return seed;
    }
};

unordered_map<State, int, StateHash> memo;

int calc(int remaining, int a, int b, int c, int d) {
    a = min(a, h);
    b = min(b, h);
    c = min(c, h);
    d = min(d, h);

    if (remaining < h && a == 0) return static_cast<int>(plough[remaining]);
    if (remaining == 0) return 0;

    State state{remaining, a, b, c, d};
    auto it = memo.find(state);
    if (it != memo.end()) return it->second;

    ll result = 0;

    if (a < h)
        result += calc(remaining - 1, 0, b + 1, c + 1, d + 1);
    else
        result += calc(remaining - 1, b + 1, c + 1, d + 1, h);

    if (b < h)
        result += calc(remaining - 1, 0, a + 1, c + 1, d + 1);
    else
        result += calc(remaining - 1, a + 1, c + 1, d + 1, h);

    if (c < h)
        result += calc(remaining - 1, 0, a + 1, b + 1, d + 1);
    else
        result += calc(remaining - 1, a + 1, b + 1, d + 1, h);

    if (d < h)
        result += calc(remaining - 1, 0, a + 1, b + 1, c + 1);
    else
        result += calc(remaining - 1, a + 1, b + 1, c + 1, h);

    int answer = static_cast<int>(result % lots);
    memo.emplace(state, answer);
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> h;

    plough.resize(n + 1);
    plough[0] = 1;
    for (int i = 0; i < n; ++i)
        plough[i + 1] = (plough[i] * 4) % lots;

    cout << calc(n, 0, 0, 0, 0) % lots << '\n';
    return 0;
}

