#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <unordered_map>
#include <vector>
using namespace std;

using ll = long long;
const ll MOD = 1000000009LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, h;
    cin >> n >> h;

    using State = array<int, 4>;

    auto encode = [h](const State& state) {
        uint64_t key = 0;
        const uint64_t base = static_cast<uint64_t>(h) + 1;
        for (int value : state)
            key = key * base + static_cast<uint64_t>(value);
        return key;
    };

    vector<State> states;
    vector<array<int, 4>> transitions;
    unordered_map<uint64_t, int> index;

    State initial{0, 0, 0, 0};
    states.push_back(initial);
    index.emplace(encode(initial), 0);

    for (size_t p = 0; p < states.size(); ++p) {
        const State state = states[p];
        array<int, 4> nextIndices{};

        for (int chosen = 0; chosen < 4; ++chosen) {
            State next = state;

            if (state[chosen] < h) {
                for (int i = 0; i < 4; ++i)
                    next[i] = (i == chosen ? 0 : min(h, state[i] + 1));
            } else {
                for (int i = 0; i < 4; ++i)
                    next[i] = (i == chosen ? h : min(h, state[i] + 1));
            }

            sort(next.begin(), next.end());
            uint64_t key = encode(next);

            auto it = index.find(key);
            if (it == index.end()) {
                int id = static_cast<int>(states.size());
                states.push_back(next);
                index.emplace(key, id);
                nextIndices[chosen] = id;
            } else {
                nextIndices[chosen] = it->second;
            }
        }

        transitions.push_back(nextIndices);
    }

    vector<int> previous(states.size(), 0), current(states.size(), 0);

    for (size_t i = 0; i < states.size(); ++i) {
        if (h > 0 && states[i][0] == 0)
            previous[i] = 1;
    }

    ll powerOfFour = 1;

    for (int remaining = 1; remaining <= n; ++remaining) {
        powerOfFour = powerOfFour * 4 % MOD;

        for (size_t i = 0; i < states.size(); ++i) {
            if (remaining < h && states[i][0] == 0) {
                current[i] = static_cast<int>(powerOfFour);
            } else {
                ll result = 0;
                for (int j = 0; j < 4; ++j)
                    result += previous[transitions[i][j]];
                current[i] = static_cast<int>(result % MOD);
            }
        }

        previous.swap(current);
    }

    cout << previous[0] << '\n';
    return 0;
}

